(1727443, 232803, 39560, '<td valign="top">pic looks alittle grainy and maybe crop. I think cropping the glass bubble and the hot tube and leaving the rest of the stuff out of the pic would be better.</td>', 'pic looks alittle grainy and maybe crop. I think cropping the glass bubble and the hot tube and leaving the rest of the stuff out of the pic would be better.', '2005-09-21 14:07:35.000000', NULL, 1),
(1727459, 231949, 39560, '<td valign="top">The color of the leaf doesn''t help to this pic. Focus could be better. Water droplets aren''t bubbles either.</td>', 'The color of the leaf doesn''t help to this pic. Focus could be better. Water droplets aren''t bubbles either.', '2005-09-21 14:12:54.000000', NULL, 1),
