(1727605, 234136, 43565, '<td valign="top">I would like to see the rest of her head, and also the face of the dog.</td>', 'I would like to see the rest of her head, and also the face of the dog.', '2005-09-21 15:02:00.000000', NULL, 1),
(1727618, 232279, 43565, '<td valign="top">I don''t see a bubble!</td>', 'I don''t see a bubble!', '2005-09-21 15:05:38.000000', NULL, 1),
