(1727806, 231944, 43565, '<td valign="top">The bubbles don''t really show up (except the blurry colors), and the child''s hand is way too red.</td>', 'The bubbles don''t really show up (except the blurry colors), and the child''s hand is way too red.', '2005-09-21 16:10:37.000000', NULL, 1),
(1727815, 233789, 43434, '<td valign="top">I like the concept .. but on execution with the bubble not being focused it has lost some of the impact ...</td>', 'I like the concept .. but on execution with the bubble not being focused it has lost some of the impact ...', '2005-09-21 16:12:54.000000', NULL, 1),
