(1727840, 234563, 43565, '<td valign="top">I would like to see her whole face, and I would like to see all of the bubbles (in focus).</td>', 'I would like to see her whole face, and I would like to see all of the bubbles (in focus).', '2005-09-21 16:18:39.000000', NULL, 1),
