INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1727875, 234292, 20530, '<td valign="top">It''s a bubble; so I gave it points for meeting the challenge. Otherwise, it''s dark, blurry, unattractive background, unappealing color and too much glare to suite my taste. Don''t feel bad, I''m in the same boat with you on this challenge. Hope we both do better next time!</td>', 'It''s a bubble; so I gave it points for meeting the challenge. Otherwise, it''s dark, blurry, unattractive background, unappealing color and too much glare to suite my taste. Don''t feel bad, I''m in the same boat with you on this challenge. Hope we both do better next time!', '2005-09-21 16:27:28.000000', NULL, 1),
(1727891, 231597, 39349, '<td valign="top">Awesome is all I can say about this. One of only a few  that really nailed this challenge. You are my hero!</td>', 'Awesome is all I can say about this. One of only a few  that really nailed this challenge. You are my hero!', '2005-09-21 16:32:05.000000', NULL, 1),
(1727893, 234624, 20530, '<td valign="top">From a technical standpoint it''s good, except the hotspot on the wall. I''m not realy crazy about the crop, but it''s in focus and seems to capture a playful, carefee attitude. The reason I didn''t vote it higher happens to be a matter of personal taste. I''d be happy to explain that in a pm, but would rather not leave it as a comment.</td>', 'From a technical standpoint it''s good, except the hotspot on the wall. I''m not realy crazy about the crop, but it''s in focus and seems to capture a playful, carefee attitude. The reason I didn''t vote it higher happens to be a matter of personal taste. I''d be happy to explain that in a pm, but would rather not leave it as a comment.', '2005-09-21 16:32:30.000000', NULL, 1),
(1727894, 231949, 39664, '<td valign="top">I think those are water droplets, not bubbles.  Love the DOF and clarity of the water.</td>', 'I think those are water droplets, not bubbles.  Love the DOF and clarity of the water.', '2005-09-21 16:32:58.000000', NULL, 1),
(1727897, 233402, 15711, '<td valign="top">SO CUTE!  The filtration is perfect.  The tub makes the shot. I''m so used to looking at rule of thirds, I had to adjust my way of thinking and this is AWESOME&gt; Perfect contrast and lighting as well.  His pure delight is just wonderful. 10</td>', 'SO CUTE!  The filtration is perfect.  The tub makes the shot. I''m so used to looking at rule of thirds, I had to adjust my way of thinking and this is AWESOME> Perfect contrast and lighting as well.  His pure delight is just wonderful. 10', '2005-09-21 16:33:25.000000', NULL, 1),
(1727900, 233030, 39664, '<td valign="top">Wish the stuff bubbling out of the radiator were more defined.  It looks more like a hot spot to me.  The concept and set up are good.</td>', 'Wish the stuff bubbling out of the radiator were more defined.  It looks more like a hot spot to me.  The concept and set up are good.', '2005-09-21 16:34:16.000000', NULL, 1),
