(1737974, 233785, 41675, '<td valign="top">For me, I would have liked to have scene this with a bit more focus on the cup itself, and perhaps removing that object in the back left side. I like the use of black and white.</td>', 'For me, I would have liked to have scene this with a bit more focus on the cup itself, and perhaps removing that object in the back left side. I like the use of black and white.', '2005-09-25 21:19:58.000000', NULL, 1),
(1737975, 233943, 41675, '<td valign="top">A funky little abstract bubble. Bumping up after a second look.</td>', 'A funky little abstract bubble. Bumping up after a second look.', '2005-09-25 21:20:26.000000', NULL, 1),
(1737976, 232910, 41675, '<td valign="top">I find the thick black border a bit overpowering from the monochrome grays of your photo, and the shot is appearing grainy and out of focus to me. Fun little "alien" though.</td>', 'I find the thick black border a bit overpowering from the monochrome grays of your photo, and the shot is appearing grainy and out of focus to me. Fun little "alien" though.', '2005-09-25 21:21:33.000000', NULL, 1),
(1737979, 234292, 41675, '<td valign="top">I wonder how this would look with a more vivid color background and a bit more focus on the bubble. The flash seems a bit harsh, but I know those bubbles are hard to photograph.</td>', 'I wonder how this would look with a more vivid color background and a bit more focus on the bubble. The flash seems a bit harsh, but I know those bubbles are hard to photograph.', '2005-09-25 21:22:37.000000', NULL, 1),
