(1745210, 233764, 5112, '<td valign="top">Jean, many, many congratulations on your ribbon!  It''s good to see your picture on the front page (again) :)</td>', 'Jean, many, many congratulations on your ribbon!  It''s good to see your picture on the front page (again) :)', '2005-09-28 12:05:14.000000', NULL, 0),
